Class Employee
  Define name As String;

  Method Constructor(employeeName As String)
    This.name <- employeeName;
  EndMethod

  Method Introduce() As String
    Return "Hello, I am " + This.name;
  EndMethod
EndClass

Class Cashier Inherits From Employee
  Method Constructor(employeeName As String)
    Super.constructor(employeeName);
  EndMethod

  Method Introduce() As String
    Return Super.Introduce() + " and I work the till";
  EndMethod
EndClass

Algorithm Kiosk
  Define name, job As String;
  Read name;
  Read job;
  Define person As Employee <- New Employee(name);
  If job = "cashier" Then
    person <- New Cashier(name);
  EndIf
  Write person.Introduce();
EndAlgorithm
